// Generated by Cypress Author on 2026-11-01.
// This isolated regression is deliberately outside tests/e2e/**/*.cy.ts.
describe('Runner UI regression', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.get('[data-cy="fixture-state"]').should('have.text', 'pending');
  });

  it('RUNNER-01 executes a page without mounting the command reporter', () => {
    cy.then(() => {
      // Inspect the real runner DOM; a launch-option assertion cannot prove this.
      const reporterPresent =
        window.top.document.querySelector('#unified-reporter') !== null;
      cy.request('POST', '/__runner_probe', {
        id: 'RUNNER-01',
        reporterPresent,
      })
        .its('status')
        .should('equal', 204)
        .then(() => {
          expect(reporterPresent, 'RUNNER_REPORTER_ABSENT').to.equal(false);
        });
    });
  });

  it('RUNNER-02 retries the assertion until the local fixture changes', () => {
    cy.document().then((document) => {
      const viewportWidth = document.defaultView.innerWidth;
      const viewportHeight = document.defaultView.innerHeight;
      expect(viewportWidth, 'AUT viewport width').to.equal(1280);
      expect(viewportHeight, 'AUT viewport height').to.equal(900);
      const element = document.querySelector('[data-cy="fixture-state"]');
      const initialState = element.textContent;
      let retries = 0;
      // cy.on is scoped to this test. No timer or test-level retry is involved.
      cy.on('command:retry', () => {
        retries += 1;
        if (retries === 1) element.textContent = 'ready';
      });
      cy.get('[data-cy="fixture-state"]')
        .should('have.text', 'ready')
        .then(($element) => {
          expect(initialState).to.equal('pending');
          expect(retries).to.be.greaterThan(0);
          expect($element.text()).to.equal('ready');
          cy.request('POST', '/__runner_probe', {
            id: 'RUNNER-02',
            retries,
            initialPending: initialState === 'pending',
            finalReady: $element.text() === 'ready',
            viewportWidth,
            viewportHeight,
          })
            .its('status')
            .should('equal', 204);
        });
    });
  });

  it('RUNNER-03 exposes an assertion failure to the external result', () => {
    // Intentionally fails: run.mjs requires this exact failure, never all green.
    cy.then(() => {
      expect(false, 'RUNNER_EXPECTED_FAILURE').to.equal(true);
    });
  });
});
